//! Item identity.
//!
//! Owner: slice a.

/// 16-byte ULID of an item, generated by the caller (app, server or agent); core never creates ids on its
/// own, it asks an [`IdSource`]. Byte order is the canonical ULID big-endian layout, so the derived `Ord`
/// (lexicographic bytes) is creation-time order and the `(z, id)` tie-break is deterministic everywhere.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ItemId(pub [u8; 16]);

/// Supplies fresh item ids for edits that create items (precise-erase pieces and masks, duplicates, fills).
/// Production callers wrap a ULID generator; tests use a counter. Every call must return an id never used
/// on the page before. Core calls it in a documented, deterministic order (see each operation).
pub trait IdSource {
    /// Next unused id.
    fn next_id(&mut self) -> ItemId;
}
